#include "player.h"
#include <QTimer>
Player::Player(QObject*p):QObject(p){m=mpv_create();mpv_set_option_string(m,"vo","gpu-next");mpv_set_option_string(m,"gpu-api","d3d11");mpv_set_option_string(m,"hwdec","auto-safe");mpv_initialize(m);timer=new QTimer(this);connect(timer,&QTimer::timeout,this,&Player::poll);timer->start(500);}Player::~Player(){if(m)mpv_terminate_destroy(m);}void Player::play(const QString&u){QByteArray b=u.toUtf8();const char*a[]={"loadfile",b.constData(),nullptr};mpv_command(m,a);}void Player::pause(){int f=0;mpv_get_property(m,"pause",MPV_FORMAT_FLAG,&f);f=!f;mpv_set_property(m,"pause",MPV_FORMAT_FLAG,&f);}void Player::seek(double s){mpv_set_property(m,"time-pos",MPV_FORMAT_DOUBLE,&s);}void Player::volume(double v){mpv_set_property(m,"volume",MPV_FORMAT_DOUBLE,&v);}void Player::poll(){mpv_get_property(m,"time-pos",MPV_FORMAT_DOUBLE,&m_position);mpv_get_property(m,"duration",MPV_FORMAT_DOUBLE,&m_duration);emit changed();}
